import sys
from collections import defaultdict, deque

def solution(input_str):
    # Parse input
    data = input_str.strip().split()
    if not data:
        return None

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1

    adj = defaultdict(list)
    for i in range(m):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        adj[u].append(v)
        adj[v].append(u)

    # We need to find either:
    # 1. A simple path with length >= n/k
    # 2. k cycles with specific properties (length >= 3, not divisible by 3, with representatives)

    target_path_len = (n + k - 1) // k  # ceiling of n/k

    # SOLUTION 1: Try to find a path of length >= target_path_len
    try:
        path = find_long_path(adj, n, target_path_len)
        if path:
            return f"PATH\n{len(path)}\n" + " ".join(map(str, path)) + "\n"
    except:
        pass

    # SOLUTION 2: Try to find k cycles with representatives
    try:
        cycles = find_k_cycles_with_reps(adj, n, k)
        if cycles:
            result = "CYCLES\n"
            for cycle in cycles:
                result += f"{len(cycle)}\n" + " ".join(map(str, cycle)) + "\n"
            return result
    except:
        pass

    return "-1\n"

def find_long_path(adj, n, target_len):
    """Try to find a simple path of length >= target_len"""

    # BFS-based search for long paths
    # Since graph is dense (min degree 3), we can use DFS

    start_nodes = list(adj.keys())

    for start in start_nodes:
        # DFS with path tracking
        visited = {start}
        path = [start]

        def dfs(node):
            if len(path) >= target_len:
                return True

            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    path.append(neighbor)
                    if dfs(neighbor):
                        return True
                    path.pop()
                    visited.remove(neighbor)

            return False

        if dfs(start):
            return path

    return None

def find_k_cycles_with_reps(adj, n, k):
    """Find k cycles with representatives (unique to each cycle)"""

    cycles = []
    used_vertices = set()

    # Strategy: Find cycles of length 4, 5, 7, 8, etc. (not divisible by 3)
    # Each cycle needs a representative vertex unique to that cycle

    for _ in range(k):
        if len(cycles) + len(used_vertices) >= k:
            break

        cycle = find_cycle_not_div_by_3(adj, used_vertices)
        if cycle is None:
            break

        # Get unique representative for this cycle
        # We need a vertex that only appears in this cycle among all cycles
        # Since we're building cycles sequentially and marking used vertices,
        # the first vertex of each cycle can serve as representative
        if cycle:
            cycles.append(cycle)
            used_vertices.update(cycle)

    if len(cycles) == k:
        return cycles
    return None

def find_cycle_not_div_by_3(adj, excluded):
    """Find a cycle with length >= 3 and length not divisible by 3, avoiding excluded vertices"""

    # Try to find a cycle through each unvisited vertex
    for node in adj.keys():
        if node in excluded:
            continue

        # Try all possible starting points for this cycle
        cycle_found = find_any_cycle_from_node(adj, node, excluded)
        if cycle_found:
            return cycle_found
        if not excluded:  # Reset for next node if we started fresh
            pass

    return None

def find_any_cycle_from_node(adj, start, excluded):
    """Find a cycle starting from node using the specified start"""

    if len(excluded) > 0:
        return None

    # DFS to find small cycles
    position = {}
    visited = {start}
    path = [start]
    position[start] = 0

    stack = [start]

    # Find a back edge that creates a cycle
    for node in adj.keys():
        if node in excluded:
            continue

        # Try to find a triangle first (might not work, but worth checking)
        for middle in adj[node]:
            if middle in adj[start] and middle not in excluded:
                cycle = [start, middle, node]
                if len(cycle) >= 3 and len(cycle) % 3 != 0:
                    return cycle

    # Try to find a cycle through adjacent pairs
    for u in adj.keys():
        if u in excluded or u in visited:
            continue

        for v in adj[u]:
            if u == v:
                continue

            # Check if we can form a 4-cycle or 5-cycle
            neighbors_u = adj[u]
            neighbors_v = adj[v]

            # Get common neighbors
            for w in neighbors_v:
                if w not in excluded and w != u:
                    if w in neighbors_u:
                        cycle = [v, w, u, start] if start == adj[v][0] else [u, w, v, start]
                        if len(cycle) >= 3 and len(cycle) % 3 != 0:
                            return cycle

    return None

