def solution(input_data):
    """
    Solves the ant scattering problem on a 2D lattice.
    """
    lines = input_data.strip().split('\n')
    if not lines:
        return ''

    n, t = map(int, lines[0].split())
    queries = []
    for i in range(1, t + t):  # Read all query lines
        if i < len(lines):
            try:
                x, y = map(int, lines[i].split())
                queries.append((x, y))
            except:
                break

    results = []
    for x, y in queries:
        # Count the ants at (x, y) using combinatorial approach
        result = count_ants(n, x, y)
        results.append(str(result))

    return '\n'.join(results)


def count_ants(initial_ants, tx, ty):
    """
    Calculate the number of ants at position (tx, ty).
    Uses the property that ants follow paths from (0,0) and scattering
    depends on the combinatorial paths available.
    """
    # Distance from origin
    dist = abs(tx) + abs(ty)

    # If Manhattan distance is negative or too far, no ants can reach here
    if dist < 0 or dist > initial_ants:
        return 0

    if dist > 30000 and initial_ants <= 30000:
        # For far positions, ants cannot reach if distance > initial_ants
        return 0

    # Calculate binomial coefficient and use the pattern
    # For a position at Manhattan distance d, the number of paths is C(d, |x|) when d >= |x| + |y|
    return calculate_ant_count(initial_ants, tx, ty)


def calculate_ant_count(n, tx, ty):
    """
    More accurate implementation based on path counting.
    """
    dx = abs(tx)
    dy = abs(ty)
    dist = dx + dy

    # Ants can only reach positions where dist <= n and dist has same parity as valid steps
    if dist > n or dist < 0:
        return 0

    # Count combinations: we need dist steps, with dx going right/down
    if dist <= n:
        # Use the pattern: ways = C(dist, dx) when dist <= n
        try:
            from math import comb
            return comb(dist, dx)
        except ImportError:
            # Fallback for older Python
            return comb_fallback(dist, dx)

    return 0


def comb_fallback(n, k):
    """Fallback binomial calculation"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result


