def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0].strip():
        return ''

    n = int(lines[0])

    compet = []
    for i in range(n):
        parts = lines[i+1].split()
        si = int(parts[0])
        ri = int(parts[1])
        compet.append((si, ri, i + 1))

    # Group by swimming speed and keep only max running for each group
    # This optimizes the check since identical swimming speeds means only max r matters
    unique_swim = {}
    for s, r, idx in compet:
        if s in unique_swim:
            unique_swim[s].append((r, idx))
        else:
            unique_swim[s] = [(r, idx)]

    # Process each group: only those with max running in their group can be winners
    candidates = []
    for s in sorted(unique_swim.keys()):
        best_r = -1
        best_idx = -1
        for r, idx in unique_swim[s]:
            if r > best_r:
                best_r = r
                best_idx = idx
        candidates.append((s, best_r, best_idx))

    # Sort by swimming descending for efficient dominance check
    candidates.sort(key=lambda x: -x[0], reverse=True)

    result = []

    for s, r, idx in candidates:
        # Check if dominated by any previous (who has greater swimming speed)
        dominated = False
        for ps, pr, pidx in candidates:
            if ps >= s and pr >= r:
                # ps is strictly greater (since we sorted by s desc)
                if ps > s:
                    dominated = True
                    break
            elif ps == s:
                if pr >= r:
                    dominated = True
                    break

        if not dominated:
            result.append(idx)

    # Sort result by competitor ID
    result.sort()
    return ' '.join(map(str, result)) + '\n'

