def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse clauses
    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals_values = parts[1:]
        clauses.append(literals_values)

    # Track which clauses contain each variable
    var_inclause = [[] for _ in range(m + 1)]
    for idx, clause in enumerate(clauses):
        for lit in clause:
            var = abs(lit)
            var_inclause[var].append((idx, lit))

    # Check for variable appearing more than twice - if so, problem
    for var, occurrences in enumerate(var_inclause):
        if len(occurrences) > 2:
            # This violates the constraint, but let's continue
            pass

    # Assignment array, -1 = unassigned, 0 = false, 1 = true
    assignment = [-1] * (m + 1)

    # Constraint satisfaction
    changed = True
    while changed:
        changed = False

        # Check all clauses for unit propagation
        for idx, clause in enumerate(clauses):
            literals = clause

            # Check if clause already has conflicting assignments
            conflict = False
            for lit in literals:
                var = abs(lit)
                assigned = assignment[var]
                if assigned != -1:
                    expected = 1 if lit > 0 else 0
                    if assigned != expected:
                        conflict = True
                        break

            if conflict:
                return "NO"

            # Check if clause is satisfied by current assignments
            satisfied = False
            for lit in literals:
                var = abs(lit)
                assigned = assignment[var]
                if assigned != -1:
                    expected = 1 if lit > 0 else 0
                    if assigned == expected:
                        satisfied = True
                        break

            if satisfied:
                continue

            # Check if clause is a unit clause (only one unassigned literal)
            unassigned_literal = None
            for lit in literals:
                var = abs(lit)
                if assignment[var] == -1:
                    unassigned_literal = lit
                    break

            if unassigned_literal is None:
                # All literals are assigned but clause not satisfied - contradiction
                return "NO"
            elif unassigned_literal is not None and len(literals) - 1 > 0:
                # Check if all other literals are already assigned and don't satisfy the clause
                all_others_assigning_false = True
                for lit in literals:
                    if lit != unassigned_literal:
                        var = abs(lit)
                        if assignment[var] == 1:
                            all_others_assigning_false = False
                            break

                if all_others_assigning_false:
                    # This means unassigned literal MUST be true
                    var = abs(unassigned_literal)
                    expected = 1 if unassigned_literal > 0 else 0
                    assignment[var] = expected
                    changed = True

    # Final check for any conflicts
    for idx, clause in enumerate(clauses):
        conflict = False
        for lit in clause:
            var = abs(lit)
            if assignment[var] == lit:
                conflict = True
                break

    if conflict:
        return "NO"

    # Build result
    result = []
    for i in range(1, m + 1):
        val = assignment[i]
        result.append('1' if val == 1 else '0')

    return "YES\n" + "".join(result)

