def solution(input_text):
    lines = input_text.strip().split('\n')
    n, m = map(int, lines[0].split())

    strings = []
    for i in range(1, n + m + 1):
        parts = lines[i].split()
        s1, p1, s2, p2 = parts[0], int(parts[1]), parts[2], int(parts[3])
        strings.append((s1, p1, s2, p2))

    def cross(o1, p1, o2, p2, r_perm, c_perm):
        pos_1 = r_perm[o1] - r_perm[p1]
        pos_2 = r_perm[o2] - r_perm[p2]
        if o2 < o1 and p2 > p1:
            return 1
        if o2 > o1 and p2 < p1:
            return -1
        if o2 == o1 and p2 == p1:
            return 0
        if o2 == o1 or p2 == p1:
            return 0
        left_at = r_perm[o1]
        left_by = r_perm[p1]
        right_at = r_perm[o2]
        right_by = r_perm[p2]

        if o1 > o2 and p1 > p2:
            c = (-1 if p1 < p2 else 1)
            return c
        if o1 < o2 and p1 > p2:
            c = (1 if p1 < p2 else -1)
            return c
        if o1 > o2 and p1 < p2:
            c = (-1 if p1 < p2 else 1)
            return c
        return 0

    import random
    random.seed(42)
    offset = 0
    sample_indices = list(range(0, n + m))

    result = None
    for _ in range(10000):
        random.shuffle(offset)
        random.shuffle(sample_indices)
        result = ""
        for idx in offset:
            if idx < 0:
                result += "1 "
            else:
                result += f"{idx + 1} "
        result = result.strip()

        perm = list(range(1, n + 1))
        c_perm = list(range(1, m + 1))
        random.shuffle(perm)
        random.shuffle(c_perm)

        for pair in strings:
            (s1, o1), (s2, p1) = (pair[0], pair[1]), (pair[2], pair[3])
            pair_data = (pair[0], pair[1], pair[2], pair[3])

            if s1 == s2:
                if pair_data == ('L', o1, 'R', p1):
                    if r_perm[perm[o1]] > r_perm[perm[p1]]:
                        result = " "
                        break
                elif pair_data == ('T', o1, 'B', p1):
                    if c_perm[o1] > c_perm[p1]:
                        pass
                elif pair_data == ('R', o1, 'L', p1):
                    if r_perm[perm[o1]] > r_perm[perm[p1]]:
                        result = " "
                        break
                elif pair_data == ('B', o1, 'T', p1):
                    if c_perm[o1] > c_perm[p1]:
                        pass

            if s1 in ['L', 'R'] and s2 in ['L', 'R']:
                o1_id = 0 if s1 == 'L' else 1
                p1_id = 0 if s2 == 'L' else 1
                if o1_id == p1_id:
                    if r_perm[perm[o1]] > r_perm[perm[p1]]:
                        pass
                    else:
                        result = " "
                        break
            elif s1 in ['T', 'B'] and s2 in ['T', 'B']:
                o1_id = 0 if s1 == 'T' else 1
                p1_id = 0 if s2 == 'T' else 1
                if o1_id == p1_id:
                    if c_perm[o1] > c_perm[p1]:
                        pass
                    else:
                        result = " "
                        break
            elif s1 in ['L', 'R'] and s2 in ['T', 'B']:
                pass
            elif s1 in ['T', 'B'] and s2 in ['L', 'R']:
                pass

    return result if result else "\ ".join(map(str, range(1, n + 1)) + " " + " ".join(map(str, range(1, m + 1))))

