def solution(s):
    """
    Solves the chessboard problem where we need to place chessmen in pairs such that
    each pair has Manhattan distance exactly 3. Returns the maximum number of chessmen
    that can be placed.
    """
    n, m = map(int, s.strip().split())

    # If either dimension is <= 2, no valid pairs can be formed
    # (maximum possible Manhattan distance is too small)
    if min(n, m) <= 2:
        return '0'

    # For n, m >= 3, we can place almost all cells
    # If total cells is odd, one cell will remain unused
    # If total cells is even, we can use all cells
    total = n * m
    if total % 2 == 1:
        return str(total - 1)
    else:
        return str(total)

