def solution(input_str):
    lines = input_str.strip().split('\n')
    N, M = map(int, lines[0].split())
    A = list(map(int, lines[1].split()))

    a_set = set(A)

    # Generate candidates from A+A (sumset modulo M)
    candidates = set()
    for a1 in A:
        for a2 in A:
            candidates.add((a1 + a2) % M)

    # Filter candidates: x is unobtainable iff (x-a) ∈ A for all a ∈ A
    result = []
