    odd_vertices = [idx + 1 for idx in range(n) if x[idx] == 1]

    if not odd_vertices:
        # No vertices need odd visits, empty path is valid
        return "0\n"

    if len(odd_vertices) == 1:
        # Single odd vertex - just output it (start = end = this vertex)
        return f"1\n{odd_vertices[0]}\n"

    # Check that all odd vertices are in the same connected component
    visited_check = {odd_vertices[0]}
    queue_check = deque([odd_vertices[0]])

    while queue_check:
        u = queue_check.popleft()
        for v in adj[u]:
            if v not in visited_check:
                visited_check.add(v)
                queue_check.append(v)

    for v in odd_vertices:
        if v not in visited_check:
            return "-1\n"

