        # BFS from path[-1] to target
        visited_bfs = {path[-1]}
        queue_bfs = deque([(path[-1], [path[-1]])])
        found_path = None

        while queue_bfs:
            u, trace = queue_bfs.popleft()
            if u == target:
                found_path = trace
                break

            for v in adj[u]:
                if v not in visited_bfs:
                    visited_bfs.add(v)
                    queue_bfs.append((v, trace + [v]))

