                valid = False
                break

        if valid and total > best_total:
            best_total = total
            best_perm = perm[:]

    # Fallback: deterministic greedy if needed
    if best_total == 0:
        perm = [0] * (n + 1)
        used = [False] * (n + 1)
        total = 0

