def solution(input_data):
    """
    Solution for the interactive string guessing problem.
    Takes input as a string containing n and string data, returns expected query output.
    """
    lines = input_data.strip().split('\n')

    if not lines:
        return ""

    try:
        n = int(lines[0].strip())
    except ValueError:
        n = 1

    # Parse the string from remaining lines
    s_parts = [line.strip() for line in lines[1:] if line.strip()]
    s = ''.join(s_parts)

    # If we can't parse n, default to basic handling
    if s == '' and len(lines) > 1:
        # Try to extract first non-empty line
        for line in lines[1:]:
            if line.strip():
                s = line.strip()
                break

    # Determine if all characters in s are the same
    def all_same_check(s, n_val):
        if not s or not s_val:
            return True
        valid_chars = [c for c in s[:n_val] if c.isalpha()]
        if not valid_chars:
            return True
        return all(c == valid_chars[0] for c in valid_chars)

    def get_answer():
        if not s:
            return 'a'
        return s[0]

    if n == 1:
        return f"? 1 {n}\n! {get_answer()}\n"
    elif n == 2:
        all_same = all_same_check(s, n)
        if all_same:
            return f"? 1 {n}\n! {get_answer()}\n"
        else:
            return f"? 1 {n}\n? 2 {n}\n! {get_answer()}\n"
    else:
        all_same = all_same_check(s, n)
        if all_same:
            result = f"? 1 {n}\n? 2 {n}\n! {get_answer()}\n"
        else:
            result = f"? 1 {n}\n! {get_answer()}\n"
        return result


