    actions = []
    for i in range(3, 3 + m):
        parts = lines[i].split()
        action, team = parts[0], int(parts[1])
        actions.append((action, team))

    @lru_cache(maxsize=None)
    def solve(idx, mask, diff):
        if idx == m:
            return diff

        action, team = actions[idx]

        if team == 1:
            best = float('-inf')
            for h in range(n):
                if not ((mask >> h) & 1):
                    if action == 'p':
                        result = solve(idx + 1, mask | (1 << h), diff + s[h])
                    else:  # ban
                        result = solve(idx + 1, mask | (1 << h), diff)
                    if result > best:
                        best = result
            return best
        else:  # team 2
            best = float('inf')
            for h in range(n):
                if not ((mask >> h) & 1):
                    if action == 'p':
                        result = solve(idx + 1, mask | (1 << h), diff - s[h])
                    else:  # ban
                        result = solve(idx + 1, mask | (1 << h), diff)
                    if result < best:
                        best = result
            return best

    result = solve(0, 0, 0)
    return str(result)

