# For n = p1^a1 * p2^a2 * ... * pk^ak
# f_r(n) = product over all i of C(a_i + r, r)

def solve_r_n(r, n):
    if n == 1:
        return 1  # Only (1,1) factor

    # Count prime factors with their exponents
    temp = n
    result = 1

    d = 2
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            # For prime factor with exponent count, contribution is C(count + r, r)
            result = result * nCr_mod(count + r, r) % MOD
        d += 1

    if temp > 1:
        # Last prime factor has exponent 1
        result = result * nCr_mod(1 + r, r) % MOD

    return result

