    lines = input_str.strip().split('\n')
    n = int(lines[0]) if lines else 0

    pairs_by_idx = {}  # 1-indexed query -> (a, b)
    parsed_queries = []

    for i in range(1, min(n + 1, len(lines))):
        line = lines[i]
        parts = line.split()
        t = int(parts[0])
        if t == 1:
            a = int(parts[1])
            b = int(parts[2])
            pairs_by_idx[i] = (a, b)
            parsed_queries.append(('ADD', i, a, b))
        elif t == 2:
            idx = int(parts[1])
            parsed_queries.append(('REMOVE', idx))
        else:
            q = int(parts[1])
            parsed_queries.append(('QUERY', q))

    active_set = set()
    current_hull = []

    def build_hull(points):
        if len(points) == 0:
            return []
        if len(points) == 1:
            return points
        pts = sorted(points, key=lambda p: (p[0], p[1]))
        hull = []
        for p in pts:
            while len(hull) >= 2:
                p1, p2 = hull[-2], hull[-1]
                cp = (p1[1] - p2[1]) * (p[0] - p[2][0]) - (p1[0] - p[2][0]) * (p[1] - p[2][1])
                if cp <= 0:
                    hull.pop()
                else:
                    break
            hull.append(p)
        return sorted(hull, key=lambda p: p[0])

    def find_max_on_hull(hull, q):
        n = len(hull)
        if n == 0:
            return float('-inf')
        if n == 1:
            return hull[0][0] * q + hull[0][1]

        lo, hi = 0, n - 1
        while lo < hi:
            mid = (lo + hi) // 2
            v1 = hull[mid][0] * q + hull[mid][1]
            v2 = hull[mid + 1][0] * q + hull[mid + 1][1]
            if v1 < v2:
                lo = mid + 1
            else:
                hi = mid

        best = -float('inf')
        if lo < n:
            best = max(best, hull[lo][0] * q + hull[lo][1])
        if lo + 1 < n:
            best = max(best, hull[lo + 1][0] * q + hull[lo + 1][1])

        return best

    results = []

    for query in parsed_queries:
        if query[0] == 'ADD':
            _, _, a, b = query
            active_set.add((a, b))
            current_hull = build_hull(list(active_set))

        elif query[0] == 'REMOVE':
            _, idx = query
            pair = pairs_by_idx.get(idx)
            if pair is not None and pair in active_set:
                active_set.remove(pair)
                current_hull = build_hull(list(active_set))

        elif query[0] == 'QUERY':
            _, q = query
            if len(current_hull) == 0:
                results.append("EMPTY SET")
            else:
                max_val = find_max_on_hull(current_hull, q)
                results.append(str(max_val))

    return '\n'.join(results)

