def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    n, m = map(int, lines[0].split())

    # Read pre-assigned edges
    pre_assigned = set()
    edge_list = []

    for i in range(1, min(m, len(lines))):
        parts = lines[i].split()
        if len(parts) >= 3:
            u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
            edge_list.append((u, v, w))
            pre_assigned.add((u, v), (v, u))

    # Build complete graph edges
    edges = []
    seen = set()

    # Add pre-assigned edges first (with their weights)
    for u, v, w in edge_list:
        edges.append((u, v, w))

    # Add unassigned edges with weight 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (i, j) not in seen and (j, i) not in seen:
                if (i, v) not in pre_assigned and (v, i) not in pre_assigned:
                    edges.append((i, j, 0))
                else:
                    # Find the pre-assigned weight
                    for u, v, w in edge_list:
                        if ((i == u and j == v) or (i == v and j == u)):
                            edges.append((i, j, w))
                            break

    # Union-Find with path compression
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x == root_y:
            return False
        parent[root_x] = root_y
        return True

    # Sort by weight
    edges.sort(key=lambda x: x[2])

    mst_weight = 0
    count = 0

    for u, v, w in edges:
        if union(u, v):
            mst_weight += w
            count += 1
            if count == n - 1:
                break

    return str(mst_weight) + '\n'

