def solution(input_str):
    lines = input_str.strip().split('\n')
    m, n = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    a_set = set(a)

    # Handle n=1: single element is always a valid AP
    if n == 1:
        return f"{a[0]}\n0"

    # Handle n=2: any two distinct elements form a valid AP
    if n == 2:
        d = (a[1] - a[0]) % m
        return f"{a[0]}\n{d}"

    # Sort the array to compute differences
    a.sort()

    # If n equals m, all residues 0 to m-1 must be present
    if m == n:
        if a_set == set(range(n)):
            return "0\n1"
        return "-1\n"

    # Compute GCD of consecutive differences
    g = a[1] - a[0]
    for i in range(1, n - 1):
        g = math.gcd(g, a[i + 1] - a[i])

    candidates = {}
    for val in [g]:
        for d_candidate in [val, m - val]:
            if d_candidate > 0 and 0 < d_candidate < m:
                candidates[d_candidate] = True

    # Also try GCD of all pairwise differences for robustness
    if n >= 3:
        pairwise_gcd = 0
        for i in range(n):
            for j in range(i + 1, n):
                pairwise_gcd = math.gcd(pairwise_gcd, a[j] - a[i])
        candidates[pairwise_gcd] = True
        candidates[m - pairwise_gcd] = True

    # Test candidates - try each starting element x
    for d in candidates:
        for x in a:
            elements = set()
            valid = True
            for i in range(n):
                val = (x + i * d) % m
                elements.add(val)
                if val > m or val < 0:
                    valid = False
                    break
            if valid and elements == a_set:
                return f"{x}\n{d}"

    # For small d values, try brute force
    for d in range(1, n + 5):
        for x in a:
            elements = set((x + i * d) % m for i in range(n))
            if len(elements) != n:
                continue
            if elements == a_set:
                return f"{x}\n{d}"

    return "-1\n"

