        min_y1 = max(1, (l + x1 - 1) // x1)
        max_y1 = min(m, r // x1)

        if min_y1 > max_y1:
            results.append("-1")
            continue

        found = False
        for y1 in range(min_y1, max_y1 + 1):
            product = x1 * y1

            # Try to find x2 > x1 such that x2 divides product and y2 = product / x2 < y1
            for x2 in range(x1 + 1, min(product, n) + 1):
                if product % x2 == 0:
                    y2 = product // x2
                    if y2 < y1:
                        results.append(f"{x1} {y1} {x2} {y2}")
                        found = True
                        break

            if found:
                break

        if not found:
            results.append("-1")

