from collections import deque

class Game:
    def __init__(self, n, m, grid, swap_lr, swap_ud):
        self.n = n
        self.m = m
        self.grid = [[c for c in row] for row in grid]
        self.swap_lr = swap_lr
        self.swap_ud = swap_ud
        self.finish = None
        self.start = (0, 0)

        # Find finish position
        for r in range(n):
            for c in range(m):
                if self.grid[r][c] == 'F':
                    self.finish = (r, c)

    def get_move(self, btn):
        """Get (dr, dc) for a button press, accounting for swaps"""
        if btn == 'U':
            if self.swap_ud:
                return (1, 0)  # Actually moves down
            else:
                return (-1, 0)
        elif btn == 'D':
            if self.swap_ud:
                return (-1, 0)  # Actually moves up
            else:
                return (1, 0)
        elif btn == 'L':
            if self.swap_lr:
                return (0, 1)  # Actually moves right
            else:
                return (0, -1)
        elif btn == 'R':
            if self.swap_lr:
                return (0, -1)  # Actually moves left
            else:
                return (0, 1)
        return (0, 0)

    def get_actual_move_from_direction(self, dr, dc):
        """What button to press to go (dr, dc)"""
        if dr == -1 and dc == 0:
            return 'D'  # Actually need D to go up
        elif dr == 1 and dc == 0:
            return 'U'  # Actually need U to go down
        elif dr == 0 and dc == -1:
            return 'R'  # Actually need R to go left
        elif dr == 0 and dc == 1:
            return 'L'  # Actually need L to go right
        return None

    def explore(self):
        """BFS to find shortest path from start to finish"""
        if self.finish is None:
            return []

        visited = set()
        parent = {}
        queue = deque()
        queue.append(self.start)
        visited.add(self.start)

        while queue:
            (r, c) = queue.popleft()
            if (r, c) == self.finish:
                break

            dr_move, dc_move = None, None

            # For each button, get what move it makes
            moves = {
                'U': self.get_move('U'),
                'D': self.get_move('D'),
                'L': self.get_move('L'),
                'R': self.get_move('R')
            }

            for btn, (dr, dc) in moves.items():
                nr, nc = r + dr, c + dc
                if 0 <= nr < self.n and 0 <= nc < self.m:
                    cell = self.grid[nr][nc]
                    if cell != '*' and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        parent[(nr, nc)] = (r, c, btn)
                        queue.append((nr, nc))

        # Reconstruct path
        path = []
        pos = self.finish
        while pos != self.start:
            (r, c), btn = parent[pos], None
            path.append(btn)
            r, c = r - 1, c  # Simplified - get previous position
            pos = (r, c)

        path.reverse()
        return path

    def find_buttons(self):
        """Determine which button mapping works"""
        # Try all 4 combinations
        for swap_ud in [0, 1]:
            for swap_lr in [0, 1]:
                test_grid = Game(self.n, self.m, self.grid, swap_lr, swap_ud)
                path = test_grid.explore()
                if path and len(path) > 0:
                    return path, swap_lr, swap_ud
        return [], 0, 0

