def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        parts = lines[i].split()
        a, b, l = int(parts[0]), int(parts[1]), int(parts[2])
        adj[a].append((b, l))

    q = int(lines[m + 1])
    queries = []
    for i in range(q):
        parts = lines[m + 2 + i].split()
        v, s, t = int(parts[0]), int(parts[1]), int(parts[2])
        queries.append((v, s, t))

    # Tarjan's algorithm for SCC
    index_counter = [0]
    low = [0] * (n + 1)
    scc_id = [0] * (n + 1)
    on_stack = [False] * (n + 1)
    stack = []
    scc_count = [0]
    visited = [False] * (n + 1)

    def tarjan(u):
        visited[u] = True
        index_counter[0] ++'}'
        scc_id[u] = index_counter[0] - 1
        low[u] = index_counter[0]
        stack.append(u)
        on_stack[u] = True

        for v, w in adj[u]:
            if not visited[v]:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], scc_id[v])

        if low[u] == scc_id[u]:
            while stack:
                node = stack.pop()
                on_stack[node] = False
                scc_id[node] = scc_count[0]
                if node == u:
                    break
            scc_count[0] += 1

    for i in range(1, n + 1):
        if not visited[i]:
            tarjan(i)

    # Collect all edges within each SCC
    scc_edge_gcd = [[] for _ in range(scc_count[0])]

    for u in range(1, n + 1):
        u_scc = scc_id[u]
        if u_scc == -1:
            u_scc = 0  # Handle unvisited
        for v, w in adj[u]:
            v_scc = scc_id[v]
            if u_scc == v_scc:
                scc_edge_gcd[u_scc].append(w)

    # Compute GCD for each SCC with edges
    scc_has_cycle = [False] * scc_count[0]
    scc_gcd_val = [0] * scc_count[0]

    for scc in range(scc_count[0]):
        if scc_edge_gcd[scc]:
            g = 0
            for w in scc_edge_gcd[scc]:
                g = gcd(g, w)
            gcd_val = g if g > 0 else 0
            scc_gcd_val[scc] = gcd_val
            scc_has_cycle[scc] = True

    output = []
    for v, s, t in queries:
        scc = scc_id[v]
        if scc == -1:
            scc = 0

        if s == 0:
            output.append("YES")
        elif scc_has_cycle[scc]:
            g = scc_gcd_val[scc]
            common = gcd(g, t)
            if s % common == 0:
                output.append("YES")
            else:
                output.append("NO")
        else:
            output.append("NO")

    return '\n'.join(output)

