    for rid, (l, r, x, c) in enumerate(restrictions):
        for pos in range(l, r + 1):
            pos_constraints[pos].append((rid, x, c))

    # Memoization: dp[pos][mask] = max profit from position pos to n
    # with 'mask' representing violated restrictions
    memo = {}

    def dp(pos, mask):
        if pos >= n:
            return 0

        state = (pos, mask)
        if state in memo:
            return memo[state]

        max_profit = 0

        # Try each possible height at current position
        for height in range(h + 1):
            # Create new mask if we violate any previously unviolated restrictions
            new_mask = mask
            for rid, x, c in pos_constraints[pos]:
