                    new_mask |= (1 << rid)  # Mark as violated

            # Gain is height^2, subtract fine for new violations at this position
            profit = height * height + dp(pos + 1, new_mask)
            max_profit = max(max_profit, profit)

        memo[state] = max_profit
        return max_profit

    result = dp(0, 0)
