def compute_min_moves(n, A, B):
    """Compute minimum moves using graph approach."""
    # Build a graph where nodes are characters 'a'-'t'
    # Edges represent transformations needed
    size = 20
    adj = {}
    for i in range(size):
        adj[i] = set()

    for i in range(n):
        if A[i] != B[i]:
            u = ord(A[i]) - ord('a')
            v = ord(B[i]) - ord('a')
            adj[u].add(v)

    # Count unique transformations needed
    edges = set()
    for u in adj:
        for v in adj[u]:
            edges.add((u, v))

    # Each connected component needs 1 move per distinct target
    # Use union-find to count components
    parent = list(range(20))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    for u in adj:
        for v in adj[u]:
            union(u, v)

    # Count components that need transformation
    components_needing_move = 0
    for i in range(20):
        if adj[i]:  # This character needs transformation
            root = find(i)
            if root == i:
                components_needing_move += 1

    return components_needing_move

