        maxx = int(parts[0])
        maxy = int(parts[1])
        w = int(parts[2])
    except (ValueError, IndexError):
        return "-1"

    # Trivial upper bound check
    if maxx * maxy < w:
        return "-1"

    # Precompute reverse values for range used
    limit = max(maxx, maxy)
    rev_cache = [0] * (limit + 1)
    for i in range(1, limit + 1):
        rev_cache[i] = rev(i)

    # For each a in [1, maxx], find all b in [1, maxy] where (a, b) is lucky
    # lucky_for_a[a] = list of b values
    lucky_for_a = [[] for _ in range(maxx + 1)]

    for a in range(1, maxx + 1):
        ra = rev_cache[a]
        if ra == 0:
            continue
        for b in range(1, maxy + 1):
            rb = rev_cache[b]
            if rb == 0:
                continue
            # Check: a * b = rev(a) * rev(b)
            if a * b == ra * rb:
                lucky_for_a[a].append(b)

    # Now iterate x from 1 to maxx, accumulating lucky counts
    # For each x, use binary search to find minimum y giving >= w lucky tickets
    current_lucky_over_y = [0] * (maxy + 1)  # lucky count for each y when x=0

    min_x = -1
    min_y = -1
    min_total = float('inf')
    found = False

    for x in range(1, maxx + 1):
        # Add lucky pairs from this new series x
        for b in lucky_for_a[x]:
            for y_val in range(b, maxy + 1):
                current_lucky_over_y[y_val] += 1

        # Check if we have at least w lucky tickets with the current x
        needs_y_binary = False

        if current_lucky_over_y[maxy] < w:
            continue  # No y will work for this x

        # Binary search for minimum y where sum reaches w
        # We need to find the first y where the cumulative lucky count >= w
        best_y = -1
        cumulative = 0
        for y_idx in range(1, maxy + 1):
            cumulative += current_lucky_over_y[y_idx]
            if cumulative >= w:
                best_y = y_idx
                break

        if best_y != -1:
            total_tickets = x * best_y
            if total_tickets <= min_total:
                min_x = x
                min_y = best_y
                min_total = total_tickets
                found = True

    if found:
        return f"{min_x} {min_y}\n"
    else:
